function loadProfile(){try{return {...{coins:300,unlocked:[],skins:{},inventory:{idols:0,extraVotes:0},stats:{played:0,wins:0,best:0,votesGiven:0,votesReceived:0,idolsFound:0,used:{}}},...JSON.parse(localStorage.getItem(MEMKEY)||'{}')}}catch{return {coins:300,unlocked:[],skins:{},inventory:{idols:0,extraVotes:0},stats:{played:0,wins:0,best:0,votesGiven:0,votesReceived:0,idolsFound:0,used:{}}}}}
