function A(p,small=false,click='',additional=''){if(!p)return '';let idx=p.team||0,col=idx===1?'blue':idx>=2?'purple':'';return `<div class="avatar ${col} ${small?'small-avatar':''} ${p.id===uid?'me':''} ${p.alive===false?'out':''} ${click?'btnavatar':''} ${additional}" ${click?`data-act="${click}" data-id="${esc(p.id)}" role="button" tabindex="0"`:''}><img loading="lazy" referrerpolicy="no-referrer" src="${esc(avatarImg(p))}" onerror="this.onerror=null;this.style.visibility='hidden'" alt="${esc(p.char)}"><span class="aname">${esc(p.char)}</span>${p.human?`<span class="humantag">${p.id===uid?'TU':'👤'}</span>`:''}</div>`}
function playerBy(id){return session?.players.find(p=>p.id===id)}
const humans=()=>session?.players.filter(p=>p.human)||[],alive=()=>session?.players.filter(p=>p.alive)||[],mine=()=>playerBy(uid),isHost=()=>session?.host===uid;
