function newRoom(code,name){return {code,created:now(),host:uid,hostSeen:now(),status:'waiting',phase:'lobby',episode:0,config:{...config},players:[newPlayer(uid,name,selectedChar,true)],memberUids:[uid],ready:[],chat:[],gossip:[],deck:[],challenge:null,results:null,fire:null,votes:{},ranking:[],rev:0,finalWins:{},comebackPlayed:false};}
async function makeRoom(){const name=getName();if(!name)return;config.campers=clamp(num(document.getElementById('cfg-campers')?.value)||config.campers,8,50);config.teams=clamp(num(document.getElementById('cfg-teams')?.value)||config.teams,2,6);config.teams=Math.min(config.teams,config.campers);config.merge=clamp(num(document.getElementById('cfg-merge')?.value)||Math.floor(config.campers/2),2,config.campers-1);config.idols=!!document.getElementById('cfg-idols')?.checked;config.comeback=!!document.getElementById('cfg-comeback')?.checked;config.comebackEpisode=clamp(num(document.getElementById('cfg-comeback-ep')?.value)||8,2,45);
 mode=serverReady?'online':'demo';let code=makeCode();let s=newRoom(code,name);session=s;activeCode=code;screen='game';modal='';if(mode==='online'){try{await db.collection('dinguz_rooms').doc(code).set(s);subscribe(code)}catch(e){notify('Firebase non disponibile, attivo una demo.');mode='demo';uid=pidKey;s.host=uid;s.players[0].id=uid;s.memberUids=[uid];persisting(s);subscribe(code)}}else{persisting(s);subscribe(code)}
 }

