/* Island minigames: server-authoritative rounds (persisted in each Firestore room). */
const SURVIVAL_TYPES=new Set(['nascondino','gavettone','porte','castello','coccobomba']);
function survivorName(s,id){return s.players.find(p=>p.id===id)?.char||'?'}
function survivalAreaCount(c){return c.type==='nascondino'?Math.min(30,Math.max(8,c.survival.active.length*2)):c.type==='porte'?Math.max(4,c.survival.active.length):c.type==='castello'?3:4}
function initSurvival(s){const c=s.challenge;c.deadline=now()+900000;c.survival={active:[...c.players],out:[],round:1,phase:'choose',starts:now(),until:now()+18000,choices:{},history:[],last:null,holder:c.type==='coccobomba'?choice(c.players):null,passes:0,passedAt:0};if(c.type==='coccobomba')c.survival.until=now()+rand(9500,15500)}
function chooseSurvivalZone(s,id,z){const c=s.challenge,v=c?.survival;if(!v||v.phase!=='choose'||!v.active.includes(id)||c.type==='coccobomba'||!Number.isInteger(z)||z<0||z>=survivalAreaCount(c))return false;if(['nascondino','porte'].includes(c.type)&&Object.entries(v.choices).some(([other,pos])=>other!==id&&pos===z))return false;v.choices[id]=z;return true}
function surviveRound(s){const c=s.challenge,v=c.survival,t=now();
 if(v.phase==='reveal') {if(t<v.until)return false;v.round++;v.phase='choose';v.starts=t;v.choices={};v.last=null;v.until=t+Math.max(13500,Math.min(29000,v.active.length*1450));if(c.type==='coccobomba'){v.holder=choice(v.active);v.passes=0;v.passedAt=0;v.until=t+rand(9000,15300)}return true}
 if(c.type==='coccobomba'){
  const holder=s.players.find(p=>p.id===v.holder);
  if(holder&&!holder.human&&t-v.passedAt>rand(1400,2300)&&t<v.until-1100&&v.active.length>1){let target=choice(v.active.filter(id=>id!==v.holder));v.history.push(`💣 ${holder.char} passa a ${survivorName(s,target)}`);v.holder=target;v.passes++;v.passedAt=t;return true}
  if(t<v.until)return false;
  const eliminated=v.holder;v.active=v.active.filter(id=>id!==eliminated);v.out.push(eliminated);v.last={bad:-1,removed:[eliminated],note:`💥 La Cocco-Bomba esplode! ${survivorName(s,eliminated)} è fuori.`};v.history.push(v.last.note);c.logs.push(v.last.note);
 }else{
  const waiting=v.active.filter(id=>v.choices[id]===undefined);
  for(const id of waiting){const bot=s.players.find(p=>p.id===id);if(bot&&!bot.human&&t-v.starts>750+Math.floor(Math.random()*2500)){
   const occupied=Object.values(v.choices),choices=Array.from({length:survivalAreaCount(c)},(_,i)=>i).filter(i=>!['porte','nascondino'].includes(c.type)||!occupied.includes(i));if(choices.length)v.choices[id]=choice(choices);
  }}
  if(t<v.until&&v.active.some(id=>v.choices[id]===undefined))return false;
  if(t<v.starts+2400)return false;
  for(const id of v.active.filter(id=>v.choices[id]===undefined)){let options=Array.from({length:survivalAreaCount(c)},(_,i)=>i).filter(i=>!['porte','nascondino'].includes(c.type)||!Object.values(v.choices).includes(i));v.choices[id]=options.length?choice(options):0}
  const occupied=Object.values(v.choices);const bad=choice([...new Set(occupied)]);
  let removed=v.active.filter(id=>v.choices[id]===bad);
  if(removed.length===v.active.length){v.last={bad,removed:[],note:'😱 Tutti hanno scelto la zona pericolosa: il round si ripete!'};v.history.push(v.last.note);v.phase='reveal';v.until=t+2600;return true}
  for(const id of removed){v.out.push(id)}v.active=v.active.filter(id=>!removed.includes(id));
  const names=removed.map(id=>survivorName(s,id)).join(', ');
  let zoneName=c.type==='nascondino'?HIDE_SPOTS[bad]:c.type==='gavettone'?['Spiaggia','Porto','Confessionale','Foresta'][bad]:`Porta ${bad+1}`;
  v.last={bad,removed,note:`${c.type==='gavettone'?'💦':'💥'} ${zoneName}: ${names} ${removed.length>1?'sono eliminati':'è eliminato'}!`};v.history.push(v.last.note);c.logs.push(v.last.note);
 }
 const teamsAlive=new Set(v.active.map(id=>s.players.find(p=>p.id===id)?.team));const deadTeams=Array.from({length:s.config.teams},(_,i)=>i).filter(team=>c.players.some(id=>s.players.find(p=>p.id===id)?.team===team)&&!teamsAlive.has(team));
 const done=isMerge(s)?v.active.length<=1:deadTeams.length>0;
 if(done){c.directLoser=isMerge(s)?v.out.at(-1):deadTeams[0];c.directWinner=isMerge(s)?v.active[0]:s.players.find(p=>p.id===v.active[0])?.team;c.players.forEach(id=>{let position=v.out.indexOf(id);c.scores[id]=position<0?300+v.round*3:position+1});scoreResolve(s);return true}
 v.phase='reveal';v.until=t+2900;return true;
}
function survivalView(c){const v=c.survival,t=Math.max(0,Math.ceil((v.until-now())/1000)),active=v.active.map(playerBy).filter(Boolean),meIn=v.active.includes(uid),action=v.choices[uid];const title={nascondino:'🌴 L’isola dei nascondigli',gavettone:'💦 Gavettone Dinguz',porte:'🚪 Porta Infernale',castello:'👻 Castello di Sabbia Infestato',coccobomba:'💣 Cocco-Bomba'}[c.type];let opts=[];
 if(c.type==='nascondino')opts=HIDE_SPOTS.slice(0,survivalAreaCount(c));else if(c.type==='gavettone')opts=['🏖️ Spiaggia','⚓ Porto','🎙️ Confessionale','🌲 Foresta'];else if(c.type==='castello')opts=['🚪 Porta 1','🚪 Porta 2','🚪 Porta 3'];else if(c.type==='porte')opts=Array.from({length:survivalAreaCount(c)},(_,i)=>'🚪 Porta '+(i+1));
 return `<div class="island-game"><div class="island-heading"><div><span class="eyebrow">ROUND ${v.round} · ${active.length} IN GARA</span><h2>${title}</h2></div><span class="clock">${v.phase==='reveal'?'💥 RIVELAZIONE':`⏳ ${t}s`}</span></div><div class="survival-roster">${c.players.map(playerBy).filter(Boolean).map(p=>`<div class="survival-camper ${!v.active.includes(p.id)?'knocked':''}"><img src="${esc(avatarImg(p))}" alt=""><span>${esc(p.char)}</span>${p.id===uid?'<b>TU</b>':''}</div>`).join('')}</div>
 ${v.phase==='reveal'?`<div class="island-disaster"><span class="boom">${c.type==='gavettone'?'💦':'💥'}</span><h3>${esc(v.last?.note||'Risultato del round')}</h3><p>Il round successivo sta per cominciare...</p></div>`:c.type==='coccobomba'?`<div class="bomb-arena"><span class="bomb-pulse">💣</span><h3>La bomba è nelle mani di ${esc(survivorName(session,v.holder))}!</h3><p>${v.holder===uid?'Passala a un altro concorrente prima che scoppi!':'Tieni d’occhio a chi arriva la bomba.'}</p>${v.holder===uid?`<div class="bomb-targets">${active.filter(p=>p.id!==uid).map(p=>`<button class="bomb-target" data-act="bombpass" data-id="${esc(p.id)}"><img src="${esc(avatarImg(p))}"><span>${esc(p.char)}</span></button>`).join('')}</div>`:''}</div>`:`<div class="${c.type==='nascondino'?'island-map':'door-stage'}"><div class="island-instructions">${c.type==='nascondino'?'Dinguz cercherà un nascondiglio occupato! Ogni luogo può ospitare un solo giocatore.':c.type==='gavettone'?'Spostati fra le quattro zone fino alla scadenza.':'Ogni concorrente sceglie una porta; Dinguz ne svelerà una pericolosa.'}</div><div class="${c.type==='nascondino'?'island-spots':'stage-zones'}">${opts.map((text,i)=>{const occupant=Object.entries(v.choices).find(([id,n])=>n===i)?.[0],occupied=(c.type==='nascondino'||c.type==='porte')&&occupant&&occupant!==uid;return `<button class="stage-spot ${action===i?'chosen':''}" data-act="minipick" data-value="${c.type==='nascondino'?'hide':c.type==='gavettone'?'water':c.type==='porte'?'door':'castle'}_${i}" ${!meIn||occupied?'disabled':''}><span>${esc(text)}</span>${occupant?`<span class="spot-owner">${esc(survivorName(session,occupant))}${occupied?' 🔒':''}</span>`:''}</button>`}).join('')}</div><div class="island-status">${!meIn?'Sei fuori dalla sfida. Osserva gli altri concorrenti!':action===undefined?'Scegli un posto!':`✅ Hai scelto: ${esc(opts[action])} · Puoi cambiare fino alla fine del tempo.`}</div></div>`}
 <div class="turnlog survivor-history">${v.history.slice(-7).reverse().map(x=>`<div>${esc(x)}</div>`).join('')||'La sfida ha appena avuto inizio...'}</div></div>`;
}
/* DINGUZ DICE: real reaction-time elimination, repeated each round. */
function initDinguz(s){const c=s.challenge;c.deadline=now()+900000;c.dinguz={active:[...c.players],out:[],round:1,phase:'react',began:now(),until:now()+6200,chosen:{},history:[],last:null,emoji:choice(EMOJIS)};c.emoji=c.dinguz.emoji}
function stepDinguz(s){const c=s.challenge,d=c.dinguz,t=now();if(d.phase==='reveal'){if(t<d.until)return false;d.phase='react';d.began=t;d.until=t+6200;d.chosen={};d.round++;d.emoji=choice(EMOJIS);c.emoji=d.emoji;return true}
 if(t<d.until&&d.active.some(id=>{const p=s.players.find(q=>q.id===id);return p?.human&&d.chosen[id]===undefined}))return false;
 if(t<d.began+1700)return false;
 for(const id of d.active){if(d.chosen[id]!==undefined)continue;const p=s.players.find(q=>q.id===id);d.chosen[id]=p&&!p.human?Math.max(250,Math.round(1700-(p.skill||60)*12+rand(-190,320))):9999}
 const slow=d.active.slice().sort((a,b)=>d.chosen[b]-d.chosen[a]);let removed=[slow[0]];d.out.push(...removed);d.active=d.active.filter(id=>!removed.includes(id));d.last=`🎙️ ${survivorName(s,removed[0])} esce (${d.chosen[removed[0]]>=9999?'emoji errata o mancata risposta':d.chosen[removed[0]]+' ms'}).`;d.history.push(d.last);c.logs.push(d.last);
 let deadTeams=Array.from({length:s.config.teams},(_,team)=>team).filter(team=>!d.active.some(id=>s.players.find(p=>p.id===id)?.team===team));if((isMerge(s)&&d.active.length<=1)||(!isMerge(s)&&deadTeams.length)){c.directLoser=isMerge(s)?removed[0]:deadTeams[0];c.directWinner=isMerge(s)?d.active[0]:s.players.find(p=>p.id===d.active[0])?.team;for(const id of c.players){let at=d.out.indexOf(id);c.scores[id]=at<0?500:d.out.length-at}scoreResolve(s);return true}
 d.phase='reveal';d.until=t+2700;return true;
}
function dinguzView(c){const d=c.dinguz;if(!d)return '';let active=d.active.includes(uid);return `<div class="dinguz-stage"><div class="island-heading"><div><span class="eyebrow">DINGUZ DICE · ROUND ${d.round}</span><h2>🎙️ Ascolta il conduttore!</h2></div><span class="clock">${d.phase==='reveal'?'📢 ELIMINAZIONE':Math.max(0,Math.ceil((d.until-now())/1000))+'s'}</span></div><div class="dinguz-spotlight">${d.phase==='reveal'?`<h3>${esc(d.last)}</h3>`:`<h2>${esc(d.emoji)}</h2><p>Tocca l'emoji identica a quella di Dinguz, il più veloce possibile.</p>`}</div><div class="survival-roster">${c.players.map(playerBy).filter(Boolean).map(p=>`<div class="survival-camper ${!d.active.includes(p.id)?'knocked':''}"><img src="${esc(avatarImg(p))}"><span>${esc(p.char)}</span><small>${d.chosen[p.id]!==undefined?(d.chosen[p.id]===9999?'❌':d.chosen[p.id]+' ms'):'—'}</small></div>`).join('')}</div>${d.phase==='react'&&active&&d.chosen[uid]===undefined?`<div class="emoji-keys">${EMOJIS.map(x=>`<button class="emoji-key" data-act="emoji" data-value="${x}">${x}</button>`).join('')}</div>`:`<div class="notice">${!active?'Sei fuori, osserva i concorrenti rimasti.':d.chosen[uid]!==undefined?'✅ Scelta registrata. Ora si aspettano gli altri.':'Nuovo round tra poco.'}</div>`}<div class="turnlog">${d.history.slice(-6).reverse().map(x=>`<div>${esc(x)}</div>`).join('')}</div></div>`}
/* ATTENTO AL MAGMA: actual successive 21-point rounds with D5 tiebreakers. */
function initMagma(s){const c=s.challenge;c.deadline=now()+900000;c.magma={active:[...c.players],out:[],round:1,phase:'roll',until:now()+26500,roundStart:now(),totals:{},stopped:{},tieIds:[],tieRolls:{},history:[],last:''}}
function stepMagma(s){const c=s.challenge,m=c.magma,t=now();if(m.phase==='reveal'){if(t<m.until)return false;m.round++;m.phase='roll';m.until=t+26500;m.roundStart=t;m.totals={};m.stopped={};m.last='';return true}
 if(m.phase==='roll'){
  for(const id of m.active){const p=s.players.find(q=>q.id===id);if(!p.human&&!m.stopped[id]){const target=rand(15,Math.min(22,17+Math.floor(p.skill/18)));m.totals[id]=target;m.stopped[id]=true}}
  if(t<m.until&&!m.active.every(id=>m.stopped[id]))return false;
  for(const id of m.active){if(!m.stopped[id]){m.stopped[id]=true;m.totals[id]=m.totals[id]||0}}
  let min=Math.min(...m.active.map(id=>m.totals[id]>21?-100:m.totals[id]));let worst=m.active.filter(id=>(m.totals[id]>21?-100:m.totals[id])===min);
  if(worst.length>1){m.phase='tie';m.tieIds=worst;m.tieRolls={};m.until=t+16500;m.last='🎲 Pareggio! I concorrenti a rischio lanciano il D5.';return true}
  return removeMagma(s,worst[0]);
 }
 if(m.phase==='tie'){
  for(const id of m.tieIds){const p=s.players.find(q=>q.id===id);if(!p.human&&m.tieRolls[id]===undefined)m.tieRolls[id]=rand(1,5)}
  if(t<m.until&&!m.tieIds.every(id=>m.tieRolls[id]!==undefined))return false;
  for(const id of m.tieIds)if(m.tieRolls[id]===undefined)m.tieRolls[id]=0;
  let low=Math.min(...m.tieIds.map(id=>m.tieRolls[id])),worst=m.tieIds.filter(id=>m.tieRolls[id]===low);
  if(worst.length>1){m.tieIds=worst;m.tieRolls={};m.until=t+13000;m.last='🔥 Ancora parità! Si rilancia il D5.';return true}
  return removeMagma(s,worst[0]);
 }
 return false;
}
function removeMagma(s,loser){const c=s.challenge,m=c.magma;m.active=m.active.filter(id=>id!==loser);m.out.push(loser);m.last=`🌋 ${survivorName(s,loser)} cade nel magma al round ${m.round}!`;m.history.push(m.last);c.logs.push(m.last);
 let deadTeam=Array.from({length:s.config.teams},(_,t)=>t).find(t=>!m.active.some(id=>s.players.find(p=>p.id===id)?.team===t));if((isMerge(s)&&m.active.length<=1)||(!isMerge(s)&&deadTeam!==undefined)){c.directLoser=isMerge(s)?loser:deadTeam;c.directWinner=isMerge(s)?m.active[0]:s.players.find(p=>p.id===m.active[0])?.team;for(const id of c.players){let at=m.out.indexOf(id);c.scores[id]=at<0?400:m.out.length-at}scoreResolve(s);return true}
 m.phase='reveal';m.until=now()+2800;return true}
function magmaView(c){const m=c.magma,t=Math.max(0,Math.ceil((m.until-now())/1000)),total=m.totals[uid]||0,active=m.active.includes(uid);return `<div class="magma-arena"><div class="island-heading"><div><span class="eyebrow">ROUND ${m.round} · ${m.active.length} rimasti</span><h2>🌋 Sfida del 21</h2></div><span class="clock">${t}s</span></div><div class="magma-tiles">${m.active.map(id=>{let p=playerBy(id);return `<div class="magma-player ${id===uid?'mine':''}"><img src="${esc(avatarImg(p))}"><b>${esc(p.char)}</b><span>${m.totals[id]??'🎲'} /21</span>${m.stopped[id]?'✋':''}</div>`}).join('')}</div><div class="magma-center"><strong>${total} / 21</strong><p>${m.phase==='tie'?'Dado a cinque facce: chi fa meno viene eliminato.':m.phase==='reveal'?esc(m.last):'Ogni lancio aggiunge 1–10. Se superi 21, vai fuori!'}</p>${active&&m.phase==='roll'&&!m.stopped[uid]?`<button class="btn primary bigbutton" data-act="magmaroll">🎲 LANCIA D10</button><button class="btn yellow bigbutton" data-act="magmastop">✋ Fermati a ${total}</button>`:active&&m.phase==='tie'&&m.tieIds.includes(uid)&&m.tieRolls[uid]===undefined?'<button class="btn primary bigbutton" data-act="magma5">🎲 Spareggio: lancia D5</button>':'<div class="notice">⏳ Attendi il prossimo round...</div>'}</div><div class="turnlog">${m.history.slice(-7).reverse().map(x=>`<div>${esc(x)}</div>`).join('')||'La lava comincia a ribollire...'}</div></div>`}
/* GIOCO DELL'OCA: shared turn rotation, special squares and bot turns. */
const GOOSE_SPECIAL={4:'−2',13:'−2',8:'+2',21:'+2',10:'Pozzo −2 turni',17:'Labirinto −8',29:'Labirinto −8',12:'Rilancia',27:'Rilancia',16:'×2'};
function initGoose(s){const c=s.challenge;c.deadline=now()+720000;c.goose={order:shuffle([...c.players]),positions:Object.fromEntries(c.players.map(id=>[id,0])),skip:{},finished:[],turn:0,turnAt:now(),logs:[],last:null,extra:false,moveCount:0,locked:[],relay:{}};
 if(!isMerge(s))for(let team=0;team<s.config.teams;team++){let members=c.goose.order.filter(id=>s.players.find(p=>p.id===id)?.team===team);for(let j=2;j<members.length;j++){c.goose.locked.push(members[j]);c.goose.relay[members[j%2]]=members[j]}}}
function nextGooseTurn(g){g.turn=(g.turn+1)%g.order.length;g.turnAt=now();}
function rollGoose(s,id,roll){const c=s.challenge,g=c.goose;if(g.order[g.turn]!==id||g.finished.includes(id)||g.locked.includes(id)||roll<1||roll>6)return false;
 let start=g.positions[id]||0,pos=Math.min(32,start+roll),remark='';
 if([4,13].includes(pos)){pos=Math.max(0,pos-2);remark='↩️ indietro di 2'}
 else if([8,21].includes(pos)){pos=Math.min(32,pos+2);remark='➡️ avanti di 2'}
 else if([17,29].includes(pos)){pos=Math.max(0,pos-8);remark='🌀 Labirinto: −8'}
 else if(pos===10){g.skip[id]=(g.skip[id]||0)+2;remark='🕳️ Pozzo: fermo per 2 turni'}
 else if([12,27].includes(pos)){remark='🎲 Lancio extra';g.extra=true}
 else if(pos===16){pos=Math.min(32,pos+roll*2);remark='🚀 ×2: +'+(roll*2)}
 g.positions[id]=pos;g.moveCount++;g.last={id,roll,start,pos,remark};g.logs.push(`🎲 ${survivorName(s,id)}: ${roll} → casella ${pos}${remark?' · '+remark:''}`);
 if(pos>=32&&!g.finished.includes(id)){g.finished.push(id);g.logs.push('🏁 '+survivorName(s,id)+' arriva al traguardo!');let partner=g.relay[id];if(partner){g.locked=g.locked.filter(x=>x!==partner);g.logs.push('🔓 '+survivorName(s,partner)+' inizia la staffetta!')}}
 let over=false;if(isMerge(s)){over=g.finished.length>=1}else{over=Array.from({length:s.config.teams},(_,t)=>t).every(t=>c.players.filter(pid=>s.players.find(p=>p.id===pid)?.team===t).every(pid=>g.finished.includes(pid)))}
 if(over){c.directWinner=isMerge(s)?g.finished[0]:s.players.find(p=>p.id===g.finished[0])?.team;const last=g.finished.at(-1);c.directLoser=isMerge(s)?g.finished.at(-1):s.players.find(p=>p.id===last)?.team;for(const pid of c.players){let rank=g.finished.indexOf(pid);c.scores[pid]=rank>=0?1000-rank*10:(g.positions[pid]||0)}scoreResolve(s);return true}
 if(g.extra&&pos<32){g.extra=false;g.turnAt=now();return true}
 g.extra=false;nextGooseTurn(g);return true;
}
function stepGoose(s){const c=s.challenge,g=c.goose;if(!g)return false;let guard=0;while(guard++<g.order.length){let id=g.order[g.turn];if(g.finished.includes(id)||g.locked.includes(id)){nextGooseTurn(g);continue}if(g.skip[id]>0){g.skip[id]--;g.logs.push('🕳️ '+survivorName(s,id)+' resta nel pozzo.');nextGooseTurn(g);return true}break}
 let id=g.order[g.turn],p=s.players.find(x=>x.id===id);if(p&&!p.human&&now()-g.turnAt>700)return rollGoose(s,id,rand(1,6));if(now()-g.turnAt>11000)return rollGoose(s,id,rand(1,6));return false}
function gooseView(c){const g=c.goose,current=playerBy(g.order[g.turn]);return `<div class="goose-game"><div class="island-heading"><h2>🎲 Gioco dell'Oca Tropicale</h2><span class="clock">Turno: ${esc(current?.char||'?')}</span></div><div class="goose-track">${Array.from({length:32},(_,i)=>{let pos=i+1,icons=c.players.filter(id=>g.positions[id]===pos);return `<div class="goose-square ${pos===32?'finish':''}"><b>${pos}</b><small>${GOOSE_SPECIAL[pos]||''}</small><span class="goose-pawns">${icons.map(id=>`<img src="${esc(avatarImg(playerBy(id)))}" title="${esc(survivorName(session,id))}">`).join('')}</span></div>`}).join('')}</div><div class="goose-actions"><div class="die-box">🎲</div><div><h3>${current?.id===uid?'È il tuo turno!':`Gioca ${esc(current?.char||'...')}`}</h3><p>Casella tua: ${g.positions[uid]||0}/32 · ${g.finished.length} arrivati${g.locked.includes(uid)?' · 🔒 Sei in attesa che il tuo compagno termini la prima staffetta.':''}</p>${current?.id===uid?'<button class="btn primary bigbutton" data-act="gooseroll">🎲 Lancia il D6</button>':'<div class="notice">⏳ I concorrenti giocano a turno.</div>'}</div></div><div class="turnlog">${g.logs.slice(-10).reverse().map(x=>`<div>${esc(x)}</div>`).join('')||'Il primo concorrente sta preparando il dado.'}</div></div>`}


/* D12: four team slots, with repeat throws for undersized teams. */
function initDice(s){const c=s.challenge;const needed=Object.fromEntries(c.players.map(id=>[id,1]));if(!isMerge(s)){for(let team=0;team<s.config.teams;team++){const ids=c.players.filter(id=>s.players.find(p=>p.id===id)?.team===team);for(let i=ids.length;i<4&&ids.length;i++)needed[ids[(i-ids.length)%ids.length]]++}}
 c.dice={needed,rolls:{},totals:{},last:null};}
function castDice(s,id,value){const c=s.challenge,d=c.dice;if(!d||!c.players.includes(id)||(d.rolls[id]||[]).length>=(d.needed[id]||1)||value<1||value>12)return false;
 d.rolls[id]=[...(d.rolls[id]||[]),value];d.totals[id]=(d.totals[id]||0)+value;d.last={id,value};c.logs.push('🎲 '+survivorName(s,id)+' tira D12: '+value);if(d.rolls[id].length>=d.needed[id])c.scores[id]=d.totals[id];return true}
function diceView(c){const d=c.dice,me=mine(),done=(d.rolls[uid]||[]).length>=(d.needed[uid]||1);return `<div class="dice-arena"><div class="island-heading"><div><span class="eyebrow">DADI A 12 FACCE · TURNI MANUALI</span><h2>🎲 Lancio dei Dadi</h2></div><span class="clock">${timeLeft()}s</span></div><div class="dice-faces"><div class="dice-big">${d.last?.id===uid?d.last.value:'D12'}</div><div><h3>${done?'✅ Hai completato i tuoi lanci':'Lancia il dado quando vuoi!'}</h3><p>${(d.rolls[uid]||[]).length}/${d.needed[uid]||1} tiri · Totale ${d.totals[uid]||0}</p>${!done?'<button class="btn primary bigbutton" data-act="diceroll">🎲 Tira il dado</button>':'<span class="chip">Risultato registrato</span>'}</div></div><div class="dice-scores">${c.players.map(playerBy).filter(Boolean).map(p=>`<div><img src="${esc(avatarImg(p))}"><span>${esc(p.char)}</span><b>${d.totals[p.id]||0}</b><small>${(d.rolls[p.id]||[]).length}/${d.needed[p.id]||1}</small></div>`).join('')}</div><div class="turnlog">${c.logs.slice(-12).reverse().map(x=>`<div>${esc(x)}</div>`).join('')||'I dadi sono pronti...'} </div></div>`}


/* Progressing NPC opponents: all skill games use real timed intermediate states. */
const SCORE_GAMES=new Set(['cocco','pesca','mangiate','ostacoli','ponte','puzzle','memory','dadi']);
function initBotPlans(s){const c=s.challenge;if(!SCORE_GAMES.has(c.type))return;c.botPlans={};for(const id of c.players){const p=s.players.find(q=>q.id===id);if(!p||p.human)continue;const skill=(p.skill||65)/100,limit=(GAMES.find(g=>g.id===c.type)?.duration||60)*1000;let duration=limit;
 if(c.type==='puzzle')duration=clamp(285000-160000*skill+rand(-25000,25000),50000,310000);
 else if(c.type==='memory')duration=clamp(116000-90000*skill+rand(-8500,8500),23000,130000);
 else if(c.type==='pesca')duration=(isMerge(s)?4:3)*rand(3000,4500);
 else if(c.type==='mangiate')duration=clamp(115000-61000*skill+rand(-10000,5000),49000,145000);
 else if(c.type==='ponte')duration=rand(8000,25000);
 else if(c.type==='ostacoli')duration=clamp(20000+35000*skill+rand(-8500,5000),8000,52000);
 else if(c.type==='dadi')duration=(c.dice?.needed[id]||1)*1200;
 c.botPlans[id]={duration,score:botPerformance(c.type,p),progress:-1,lastTick:-1,fishAt:0,ended:false};
 }}
function stepScoringBots(s){const c=s.challenge;if(!c||!SCORE_GAMES.has(c.type))return false;const elapsed=now()-c.started,meta=GAMES.find(g=>g.id===c.type),limit=meta.duration*1000;let changed=false;
 for(const id of c.players){const p=s.players.find(q=>q.id===id),plan=c.botPlans?.[id];if(!p||p.human||!plan||c.scores[id]!==undefined)continue;
 const progress=clamp(Math.round(elapsed/plan.duration*100),0,100);
 if(c.type==='dadi'){
  const done=(c.dice.rolls[id]||[]).length,needed=c.dice.needed[id]||1;
  if(done<needed&&elapsed>=(done+1)*1000){castDice(s,id,rand(1,12));changed=true}
  continue;
 }
 if(c.type==='pesca'){
  let a=c.actions[id]||{fishes:0,fishScore:0,history:[]},count=isMerge(s)?4:3;
  if(a.fishes<count&&elapsed>(a.fishes+1)*plan.duration/count){let zone=rand(0,4),loot=catchFish(zone);a.fishes++;a.fishScore+=loot[1];a.history.push(loot[0]);a.last=loot[0];a.zone=zone;c.actions[id]=a;if(a.fishes===count)c.scores[id]=Math.max(0,a.fishScore);changed=true}continue;
 }
 if(plan.progress!==progress&&(!c.actions[id]||c.actions[id].progress!==progress)){
  c.actions[id]={...(c.actions[id]||{}),progress};plan.progress=progress;changed=true;
 }
 if(elapsed>=plan.duration){let score=plan.score;
  if(c.type==='puzzle'||c.type==='memory')score=125+Math.max(0,Math.round((limit-plan.duration)/(c.type==='memory'?5000:10000)));
  if(c.type==='mangiate')score=205+Math.max(0,Math.round((limit-plan.duration)/1000));
  if(c.type==='ponte')score=Math.max(0,Math.min(120,Math.round((p.skill+rand(-25,15))/10)*12));
  if(c.type==='cocco')score=plan.score;
  if(c.type==='ostacoli'){const seconds=plan.duration/1000;score=Math.floor(seconds*(210+seconds*3)/18)}
  c.scores[id]=Math.max(0,Math.round(score));plan.ended=true;changed=true;
 }
 }
 if(now()>c.deadline+500){prepareChallenge(s);scoreResolve(s);return true}
 const isTimed=['cocco','ostacoli'].includes(c.type);
 if(!isTimed&&c.players.every(id=>c.scores[id]!==undefined)){scoreResolve(s);return true}
 return changed;
}

function botPerformance(type,p,elapsed=1){let skill=(p.skill||65)/100;if(type==='cocco')return Math.floor(63+skill*70+rand(-9,9));if(type==='dinguz')return Math.round(2000-1550*skill+rand(-130,270));if(type==='puzzle')return Math.floor(30+skill*62+rand(-8,8));if(type==='pesca')return Math.floor(1+skill*10+rand(-3,3));if(type==='mangiate')return Math.floor(62+skill*150+rand(-12,12));if(type==='ostacoli')return Math.floor(60+skill*205+rand(-18,18));if(type==='memory')return Math.floor(15+skill*74+rand(-8,8));if(type==='magma')return Math.floor(10+skill*11+rand(-4,2));if(type==='duelli')return Math.floor(35+skill*40+rand(-10,10));if(type==='nascondino'||type==='gavettone'||type==='porte'||type==='castello'||type==='coccobomba')return Math.floor(12+skill*80+rand(-15,15));return Math.floor(18+skill*83+rand(-16,16))}
function scoreResolve(s){const ch=s.challenge,type=ch.type;const players=ch.players.map(id=>s.players.find(p=>p.id===id)).filter(Boolean),scores={};players.forEach(p=>{let score=ch.scores[p.id];if(score===undefined){score=p.human?0:botPerformance(type,p);if(type==='duelli'){score=ch.hp[p.id]===undefined?0:ch.hp[p.id]}if(type==='dadi'){score=ch.dice?.totals[p.id]||0}if(['puzzle','memory','mangiate'].includes(type)&&ch.botPlans?.[p.id])score=Math.max(0,Math.round(ch.botPlans[p.id].progress||0)) }scores[p.id]=Math.max(0,num(score))});
 // A skillful CPU is guaranteed to be capable of scoring over 100, but human scores are never rewritten.
 if(type==='cocco'){let bots=players.filter(p=>!p.human);if(bots.length&&Math.max(...bots.map(p=>scores[p.id]))<100){let best=bots.sort((a,b)=>b.skill-a.skill)[0];scores[best.id]=Math.max(102,scores[best.id])}}
 let ordered=players.sort((a,b)=>type==='dinguz'&&!ch.dinguz?scores[a.id]-scores[b.id]:scores[b.id]-scores[a.id]);const group=!isMerge(s);let loser=null,winner=null,teamScores=[];
 if(group){for(let t=0;t<s.config.teams;t++){let groupPlayers=players.filter(p=>p.team===t);if(!groupPlayers.length)continue;let v=['puzzle','memory'].includes(type)?groupPlayers.reduce((sum,p)=>sum+Math.max(1,players.length-ordered.indexOf(p)),0):type==='dadi'?groupPlayers.reduce((sum,p)=>sum+scores[p.id],0):groupPlayers.reduce((sum,p)=>sum+scores[p.id],0)/groupPlayers.length;teamScores.push({team:t,score:Math.round(v*10)/10})}teamScores.sort((a,b)=>a.score-b.score);loser=type==='dinguz'&&!ch.dinguz?teamScores[teamScores.length-1]?.team??0:teamScores[0]?.team??0;winner=type==='dinguz'&&!ch.dinguz?teamScores[0]?.team??0:teamScores[teamScores.length-1]?.team??0}else{winner=ordered[0]?.id;loser=ordered[ordered.length-1]?.id}
 let tied=group?teamScores.length>1&&(type==='dinguz'?teamScores.at(-1).score===teamScores.at(-2).score:teamScores[0].score===teamScores[1].score):ordered.length>1&&(type==='magma'?scores[ordered.at(-1).id]===scores[ordered.at(-2).id]:scores[ordered[0].id]===scores[ordered[1].id]);
 s.results={type,scores,ordered:ordered.map(p=>p.id),teamScores,loser,winner,tied,final:isMerge(s)&&s.players.filter(p=>p.alive).length===2,logged:[...ch.logs.slice(-20)],timestamp:now()};if(type==='sasso'&&ch.rps){s.results.loser=group?ch.rpsLoserTeam:ordered.at(-1)?.id;s.results.winner=group?ch.rpsWinnerTeam:ch.rpsWinnerId;s.results.tied=false;}if(ch.directLoser!==undefined){s.results.loser=ch.directLoser;s.results.tied=false;s.results.tiePending=false;}if(ch.directWinner!==undefined){s.results.winner=ch.directWinner;}if(type==='magma'&&tied){let worst=Math.min(...ordered.map(p=>scores[p.id]));let tiePlayers=ordered.filter(p=>scores[p.id]===worst).map(p=>p.id);if(group&&tiePlayers.length<2)tiePlayers=ordered.filter(p=>p.team===loser).map(p=>p.id);if(tiePlayers.length>=2){s.results.tiePending=true;s.results.tiePlayers=tiePlayers;s.results.tieRolls={}}}s.challenge=null;setPhase(s,'result');
 if(s.results.final&&!s.results.tiePending){s.finalWins[winner]=(s.finalWins[winner]||0)+1; if(s.finalWins[winner]>=2)finishSeason(s,winner)} }
function startFire(s){const voters=s.players.filter(p=>eligibleVoter(s,p)),counts={};voters.forEach(p=>counts[p.id]=0);Object.values(s.votes).filter(Boolean).forEach(id=>{counts[id]=(counts[id]||0)+1});
 let max=Math.max(0,...Object.values(counts));let candidates=voters.filter(p=>(counts[p.id]||0)===max);let protectedIds=[];
 candidates=candidates.filter(p=>{if(p.idols>0){p.idols--;protectedIds.push(p.id);return false}return true});if(!candidates.length){let max2=Math.max(0,...voters.filter(p=>!protectedIds.includes(p.id)).map(p=>counts[p.id]||0));candidates=voters.filter(p=>!protectedIds.includes(p.id)&&(counts[p.id]||0)===max2)}
 let tie=candidates.length>1;let out=tie?null:candidates[0]?.id;let safe=voters.filter(p=>p.id!==out&&(!tie||!candidates.some(x=>x.id===p.id))).sort((a,b)=>(counts[a.id]||0)-(counts[b.id]||0)).map(p=>p.id);
 s.fire={counts,protectedIds,candidates:candidates.map(p=>p.id),tie,out,safe,revealed:0,rolls:{},pending:true,decisionRevealed:false};
 }
function eliminate(s,id){const p=s.players.find(x=>x.id===id);if(p?.alive){p.alive=false;p.placement=s.players.filter(x=>x.alive).length+1;s.ranking.push(id)} }
function resolveTie(s){let f=s.fire;if(!f?.tie)return;let all=f.candidates.every(id=>f.rolls[id]!==undefined);if(!all)return;const min=Math.min(...f.candidates.map(id=>f.rolls[id]));const worst=f.candidates.filter(id=>f.rolls[id]===min);if(worst.length>1){f.candidates=worst;f.rolls={};return}let out=worst[0];f.out=out;f.tie=false;f.decisionRevealed=true;eliminate(s,out);f.safe.push(...s.fire.candidates.filter(id=>id!==out));f.revealed=f.safe.length;}
function finishSeason(s,winnerId){let all=s.players.filter(p=>!s.ranking.includes(p.id));let winner=s.players.find(p=>p.id===winnerId)||all[0];let others=all.filter(p=>p.id!==winner.id);s.ranking.push(...others.map(p=>p.id),winner.id);s.ranking=[...new Set(s.ranking)];s.players.forEach(p=>{p.placement=s.ranking.length-s.ranking.indexOf(p.id)});s.status='finished';s.phase='end';s.winner=winner.id;s.ready=[]}
function nextEpisode(s){if(s.players.filter(p=>p.alive).length<=1){finishSeason(s,s.players.find(p=>p.alive)?.id);return}
 if(s.players.filter(p=>p.alive).length===2){s.episode++;setPhase(s,'challenge');return}
 s.episode++;if(s.config.comeback&&!s.comebackPlayed&&s.episode===s.config.comebackEpisode){s.comebackPlayed=true;setPhase(s,'comeback');s.comeback={round:1,players:shuffle(s.players.filter(p=>!p.alive)).slice(0,Math.max(2,Math.ceil(s.players.filter(p=>!p.alive).length*.6))).map(p=>p.id),rolls:{},lives:{}};s.comeback.players.forEach(id=>s.comeback.lives[id]=s.players.find(p=>p.id===id).human?2:1)}else setPhase(s,'teams')}
function transition(s){if(s.freePlay&&s.phase==='result')return;if(s.phase==='teams'){setPhase(s,'social')}else if(s.phase==='social'){setPhase(s,'challenge')}else if(s.phase==='result'){
 if(s.results.final){if(s.status==='finished')return;setPhase(s,'challenge')}else setPhase(s,'vote')
 }else if(s.phase==='fire'){if(!s.fire?.decisionRevealed||s.fire?.tie||s.fire?.revealed<s.fire?.safe.length)return;nextEpisode(s)}else if(s.phase==='comeback'){nextEpisode(s)} }
function statusLabel(){if(session?.freePlay)return 'Prova libera';return {lobby:'Sala d’attesa',teams:'Squadre',social:'Fase sociale',challenge:'Sfida',result:'Risultato',vote:'Votazione',fire:'Falò',comeback:'Comeback',end:'Finale'}[session?.phase]||'Menu'}
function timeLeft(){let c=session?.challenge,limit=c?.survival?.until||c?.dinguz?.until||c?.magma?.until||c?.deadline||0;return Math.max(0,Math.ceil((limit-now())/1000))}
function syncSeasonInventory(){if(!session||session.freePlay||session.status!=='playing'||!mine()?.human)return;let marker='dinguz_items_'+session.code;if(localStorage.getItem(marker))return;localStorage.setItem(marker,'1');if(currentProfile.inventory){currentProfile.inventory.idols=0;currentProfile.inventory.extraVotes=0;saveProfile()}}
function updateStatsOnEnd(){if(!session||session.status!=='finished'||session._processed)return;let my=mine();if(!my)return;let marker='dinguz_finished_'+session.code;if(localStorage.getItem(marker))return;localStorage.setItem(marker,'1');let st=currentProfile.stats;st.played++;if(session.winner===uid)st.wins++;st.best=st.best?Math.min(st.best,my.placement):my.placement;st.used[my.char]=(st.used[my.char]||0)+1;st.votesReceived+=my.votesReceived||0;let reward=session.winner===uid?400:Math.max(50,400-((my.placement-1)*10));currentProfile.coins+=reward;saveProfile();notify('Stagione terminata! Hai ottenuto '+reward+' monete.')}
function renderHome(){let sample=window.CHARACTERS.slice(0,28).map(c=>`<img title="${esc(c.name)}" alt="" referrerpolicy="no-referrer" loading="lazy" src="${esc(c.url)}">`).join('');return `<main class="home"><span class="tag">🔥 REALITY SHOW MULTIGIOCATORE <span class="cost">◉ ${currentProfile.coins}</span></span><h1>A Tutto<br>Pelatona Dinguz</h1><p class="lead">Alleanze, tradimenti, porte che esplodono e marshmallow al falò.<br>Solo uno porterà a casa il milione di dollari.</p><div class="homebox"><label class="fieldlabel" for="username">Il tuo nome</label><input id="username" class="field" maxlength="20" placeholder="Scegli il tuo nome" value="${esc(localStorage.getItem('dinguz_name')||'')}"><div class="formline"><button class="btn primary wide" data-act="setup">⊕ Crea la stanza (Host)</button></div><div class="formline"><input id="joincode" class="field" placeholder="CODICE STANZA" maxlength="6" style="text-align:center;letter-spacing:3px"><button class="btn cyan" data-act="join">🔗 Unisciti</button></div><div class="homeactions"><button class="btn ghost" data-act="browse">👥 Lobby online</button><button class="btn ghost" data-act="stats">📊 Statistiche</button><button class="btn yellow" data-act="shop">🛍️ Shop</button></div><button class="btn practice-btn wide" data-act="openfree">🎮 PROVA LIBERA <span>Prova qualsiasi minigioco senza iniziare una stagione</span></button></div><div class="muted" style="margin-top:13px">${serverReady?'<span class="status">● Firebase online</span> Stanza sincronizzata via Firestore.':'<span class="status offline">● Demo locale</span> Puoi giocare subito contro bot; per il multiplayer abilita Firebase.'}</div>${dbError?`<p class="small" style="max-width:540px">${esc(dbError)}</p>`:''}<div class="avatars-preview">${sample}<span class="chip">+${Math.max(0,window.CHARACTERS.length-28)} CAMPEGGIATORI</span></div></main><div class="footer">Gioco originale fan-made · ${window.CHARACTERS.length} personaggi · modalità demo e Firebase · Funziona su GitHub Pages</div>`}
function navbar(){const counts=session?.players.filter(p=>p.alive).length||0;return `<header class="topbar"><div class="logo">A TUTTO PELATONA DINGUZ</div>${session?`<span class="toppill">EP.${session.episode||'–'}</span><span class="navtag">${esc(statusLabel())}</span><span class="small">🏕️ ${counts} in gara</span>${session.status==='playing'&&!isMerge()?TEAMS.slice(0,session.config.teams).map((t,i)=>`<span class="navtag ${i===0?'orange':i===1?'blue':'violet'}">${t.emoji} ${esc(t.name)}: ${session.players.filter(p=>p.alive&&p.team===i).length}</span>`).join(''):''}<div class="nav-right"><span class="small">${isHost()?'👑 HOST':''}</span><span class="toppill">${esc(session.code)}</span><span class="small">${humans().length} online</span><button class="btn sm ghost" data-act="leave" title="Torna al menu">⇥ Esci</button></div>`:`<span class="navtag">🏝️ Reality multiplayer</span><div class="nav-right"><span class="status ${serverReady?'':'offline'}">${serverReady?'Online disponibile':'Demo disponibile'}</span></div>`}</header>`}
function side(){let me=mine();let chat=session.chat||[];return `<aside class="sidecol"><div class="paper"><div class="fakeprofile">${me?`<img src="${esc(avatarImg(me))}" onerror="this.style.display='none'" alt="">`:''}<div><b>${esc(me?.name||'Ospite')}</b> <span class="small">(${esc(me?.char||'')})</span><div class="muted">${session.status==='playing'&&me?.alive&&!isMerge()?`${TEAMS[me.team].emoji} ${TEAMS[me.team].name}`:me?.alive?'🏕️ Concorrente':'👁️ Spettatore'}</div></div></div></div><div class="paper" style="display:flex;flex-direction:column"><b>💬 Chat del campo</b><div class="chatlog" id="chatlog">${chat.length?chat.slice(-35).map(x=>`<div class="chatline"><b>${esc(x.who)}:</b> ${esc(x.text)}</div>`).join(''):'<div class="muted">Scrivi qualcosa per iniziare una conversazione!</div>'}</div><div class="chatinput"><input id="chattext" class="field" maxlength="200" placeholder="Scrivi..."><button class="btn yellow" data-act="chat">➤</button></div></div></aside>`}
function gameShell(main){const pr=session.players.filter(p=>p.human).length;return `${navbar()}<div class="container"><div class="grid2"><section class="maincol">${main}</section>${side()}</div></div>`}
function readyBox(label='Sono pronto!'){if(session.freePlay)return '';let r=session.ready||[],me=mine(),can=true;let hint='';if(session.phase==='social'&&me?.alive&&me.talks.length<1&&session.players.some(p=>p.alive&&!p.human&&p.id!==uid)){can=false;hint='Devi fare almeno un dialogo con un NPC prima di essere pronto.'}if(session.phase==='fire'&&session.fire?.pending&&(!session.fire?.decisionRevealed||session.fire.tie||session.fire.revealed<session.fire.safe.length)){can=false;hint='Aspetta che finisca la cerimonia.'}if(session.phase==='vote'||session.phase==='challenge'||session.phase==='lobby'||session.phase==='end')return '';let yes=r.includes(uid);return `<div class="paper readybox"><div><b>Pronti ${humanReadyCount()}/${humansExpected()}</b> <span class="small" style="color:#b96631">${esc(humans().filter(p=>r.includes(p.id)).map(p=>p.name).join(', '))}</span>${hint?`<div class="subtle">${hint}</div>`:''}</div><button class="btn primary" data-act="ready" ${yes||!can?'disabled':''}>${yes?'✓ Pronto!':label}</button></div>`}
