function viewLobby(){return `${stageHero('Sala d’attesa','Codice stanza '+session.code+' · scegli il personaggio e invita i tuoi amici','🏝️')}<div class="paper"><div class="playhead"><h3>Campeggiatori (${session.players.length}/${session.config.campers})</h3><button class="btn cyan" data-act="roster">🎭 Cambia personaggio</button></div><div class="avatars-row">${session.players.map(p=>A(p)).join('')}</div><div class="notice" style="margin-top:12px">${isHost()?'Sei l’host. Quando vuoi puoi iniziare: i posti vuoti saranno riempiti da NPC.':'Aspetta che l’host avvii la stagione. Puoi cambiare il tuo personaggio.'} <b>Ogni personaggio può essere scelto da una sola persona.</b></div><div class="flex wrap" style="margin-top:13px"><button class="btn ghost" data-act="copycode">📋 Copia codice ${esc(session.code)}</button>${isHost()?`<button class="btn primary" data-act="start">▶ Inizia stagione</button>`:''}</div></div><div class="paper"><h3>⚙️ Regole della stagione</h3><p class="small">${session.config.campers} concorrenti · ${session.config.teams} squadre · ${session.config.idols?'Idoli attivi':'Idoli disattivi'} · Merge a ${session.config.merge} rimasti · ${session.config.comeback?'Comeback previsto':'Nessun comeback'}</p><p class="small">Gli umani vengono separati fra i team se possibile: 3 umani e 3 team → 1,1,1. 4 umani e 3 team → 2,1,1.</p></div>`}
function viewTeams(){const s=session;return `${stageHero('Episodio '+s.episode+': i campeggiatori',isMerge()?'È il momento del merge! Ognuno gioca per sé.':'Ecco le squadre. Il team che perde andrà al falò!','🏕️')}${isMerge()?`<div class="paper"><div class="avatars-row">${s.players.filter(p=>p.alive).map(p=>A(p)).join('')}</div></div>`:`<div class="teams">${TEAMS.slice(0,s.config.teams).map((t,i)=>`<div class="team"><div class="teamhead" style="background:linear-gradient(100deg,${t.color},${t.color}bb)">${t.emoji} ${t.name} (${s.players.filter(p=>p.alive&&p.team===i).length})</div><div class="teamavatars">${s.players.filter(p=>p.alive&&p.team===i).map(p=>A(p)).join('')}</div></div>`).join('')}</div>`}<div class="paper"><b>🧠 Novità: umani in squadre differenti!</b><p class="muted">La distribuzione bilancia prima i giocatori reali; in seguito gli NPC riempiono i posti in modo uniforme.</p>${s.players.some(p=>p.idols>0&&p.id===uid)?'<span class="chip">🗿 Possiedi una statuetta dell’immunità</span>':''}</div>${readyBox()}`}
function socialCard(p){let rel=num(mine()?.relations?.[p.id]);return `<button type="button" class="avatar-choice ${socialTarget===p.id?'selected':''}" style="min-width:78px;max-width:102px" data-act="target" data-id="${esc(p.id)}"><img loading="lazy" referrerpolicy="no-referrer" src="${esc(avatarImg(p))}" alt=""><span>${esc(p.char)} ❤️${rel>0?'+':''}${rel}</span></button>`}
function viewSocial(){let me=mine(),others=session.players.filter(p=>p.alive&&!p.human&&p.id!==uid),target=others.find(p=>p.id===socialTarget)||others[0];if(target&&!socialTarget)socialTarget=target.id;let rel=num(me?.relations?.[target?.id]);let flirt=rel<0?0:rel===0?10:rel<=2?30:rel===3?50:rel===4?80:100;return `${stageHero('Fase Sociale','Puoi dialogare con due NPC diversi per episodio. Devi dialogare almeno una volta per andare avanti.','🌴')}<div class="paper"><h4>📰 Pettegolezzi dal campo</h4><div class="hscroll">${session.gossip.map(g=>`<div class="gossip ${g.good?'':'bad'}">EP ${session.episode}<div>${esc(g.t)}</div></div>`).join('')||'<div class="muted">Oggi il campo è stranamente tranquillo...</div>'}</div></div><div class="paper"><div class="playhead"><h4>🏕️ I campeggiatori</h4><span class="chip">Dialoghi ${me?.talks?.length||0}/2 · minimo 1 · bersagli diversi</span></div><div class="roster" style="max-height:300px;grid-template-columns:repeat(auto-fill,minmax(88px,1fr))">${others.map(socialCard).join('')}</div>${target?`<div class="socialpanel" style="margin-top:10px"><div class="interaction-target"><img src="${esc(avatarImg(target))}" alt="${esc(target.char)}"><div><h3>${esc(target.char)}</h3><b>❤️ Amicizia ${rel>0?'+':''}${rel}</b><div class="muted">Oggi: ${me?.talks?.includes(target.id)?'hai già dialogato con questo personaggio':'puoi interagire'}</div><div class="socialactions"><button class="btn cyan" data-act="dialogmenu" ${me?.talks?.length>=2||me?.talks?.includes(target.id)||!me?.alive?'disabled':''}>💬 Dialoga</button><button class="btn danger sm" data-act="social" data-value="minaccia">😈 Minaccia</button><button class="btn pink sm" data-act="social" data-value="flirt">💘 Flirt (${flirt}%)</button><button class="btn purple sm" data-act="social" data-value="zizzania">🔥 Metti zizzania</button></div></div></div>${dialogMenu?`<div class="socialactions" style="margin-left:8px">${[['chiacchiera','💬 Chiacchiera'],['battuta','🤣 Battuta'],['strategia','🎯 Strategia'],['punzecchia','⚡ Punzecchia']].map(([id,t])=>`<button class="btn ghost" data-act="talk" data-value="${id}">${t}</button>`).join('')}</div>`:''}</div>`:'<p>Nessun NPC disponibile al momento.</p>'}</div><div class="paper"><h4>🔐 I tuoi dialoghi privati</h4>${(me?.privateLogs||[]).slice(-9).reverse().map(l=>`<div class="dialogue"><b>EP ${l.ep} · ${esc(l.target)} · ${esc(l.mode)}</b><div class="spoken">${esc(l.line)}</div><div class="reply">${esc(l.reply)}</div><span class="small" style="color:${l.delta>=0?'#219c5b':'#c25243'}">${l.delta>=0?'+':''}${l.delta} amicizia</span></div>`).join('')||'<p class="muted">I tuoi dialoghi appariranno qui, separati dagli altri giocatori.</p>'}</div>${readyBox()}`}
function scoreBoard(scores=null,top=16,unit='pt',ascending=false){let sc=scores||session.challenge?.scores||session.results?.scores||{};let list=session.players.filter(p=>p.alive||sc[p.id]!==undefined).map(p=>({p,n:sc[p.id]??(p.human?'—':'?')})).sort((a,b)=>typeof a.n==='number'&&typeof b.n==='number'?(ascending?a.n-b.n:b.n-a.n):(typeof a.n==='number'?-1:1));return `<div class="scorelist">${list.slice(0,top).map((v,i)=>`<div class="scoreline ${v.p.id===uid?'mine':''}"><span class="meta"><span>${i+1}.</span><img src="${esc(avatarImg(v.p))}" alt=""><b>${esc(v.p.char)}${v.p.id===uid?' (TU)':''}</b></span><b>${v.n==='—'||v.n==='?'?v.n:esc(v.n)+' '+unit}</b></div>`).join('')}</div>`}
function challengeHead(){let c=session.challenge,g=gameMeta();return `<div class="paper hero"><span class="heroicon">${g.emoji}</span><div style="flex:1"><div class="flex wrap"><h2>${esc(g.name)}</h2><span class="chip">${isMerge()?'INDIVIDUALE':'A TEAM'}</span></div><p class="minigamehelp">${esc(g.help)}</p></div><span class="clock" id="miniclock">${c.type==='sasso'?'⚔️ A turni':'⏱ '+timeLeft()+'s'}</span></div>`}
