 const m=mini.puzzle,n=m.stage+3,total=n*n,pieces=document.getElementById('pieces'),grid=document.getElementById('puzzleGrid');if(!pieces||!grid)return;const ch=C(session.players.find(p=>p.id===session.challenge.players[m.stage%session.challenge.players.length])?.char||mine().char),img=ch.url;
