function puzzlePlace(index){let m=mini.puzzle;if(!m||m.selected===null)return;const n=m.stage+3,total=n*n;if(Object.values(m.placed).includes(m.selected))return;const already=m.placed[index];if(already!==undefined&&already!==index)delete m.placed[index];m.placed[index]=m.selected;m.selected=null;let good=Object.entries(m.placed).filter(([pos,part])=>Number(pos)===part).length;let before=m.stage===0?0:m.stage===1?9:25;m.score=before+good;if(good>=total){if(m.stage===2){m.score=50;submitScore(125+Math.round(timeLeft()/10),{progress:100});notify('🧩 Hai completato tutti e tre i puzzle!');return}m.stage++;m.placed={};m.order=shuffle([...Array((m.stage+3)**2).keys()]);m.selected=null;notify('🧩 Stage completato! Si passa al successivo.')}setupPuzzle()}
